import { useTranslations } from "next-intl";

// Smart collections are auto-generated by the backend in English (e.g.
// "Imported Books"). Their stable identifier is `smartKey`. Resolve the
// localized display name through the messages catalog when available, and
// fall back to the server-provided name (CUSTOM collections, or any new
// SMART key the catalog hasn't been updated for yet).

const KNOWN_SMART_KEYS = new Set(["imported-library", "public-domain-library"]);

type CollectionLike = {
  description?: string | null;
  kind: "SMART" | "CUSTOM";
  name: string;
  smartKey: string | null;
};

export function useCollectionDisplay() {
  const t = useTranslations("smartCollections");

  function name(collection: CollectionLike): string {
    if (
      collection.kind === "SMART" &&
      collection.smartKey &&
      KNOWN_SMART_KEYS.has(collection.smartKey)
    ) {
      return t(`${collection.smartKey}.name`);
    }
    return collection.name;
  }

  function description(collection: CollectionLike): string | null {
    if (
      collection.kind === "SMART" &&
      collection.smartKey &&
      KNOWN_SMART_KEYS.has(collection.smartKey)
    ) {
      return t(`${collection.smartKey}.description`);
    }
    return collection.description ?? null;
  }

  return { name, description };
}
